#include <array>
#include <cstddef>

struct Point {
    double x, y;
};

/* Count the number of Cartesian points in each quadrant.
   The vector `points` contains a list of `Point` objects.
   Store the counts in `bins` (order: I, II, III, IV).
   Points that lie on either axis are ignored.
   The implementation is safe for any number of OpenMP threads. */
void countQuadrants(const std::vector<Point>& points,
                    std::array<std::size_t, 4>& bins)
{
    // Initialise the output bins.
    bins.fill(0);

    // Parallel region with a private per‑thread accumulator.
    #pragma omp parallel
    {
        std::size_t local_bins[4] = {0, 0, 0, 0};

        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const Point& p = points[i];

            if (p.x > 0.0 && p.y > 0.0) {
                ++local_bins[0];               // Quadrant I
            } else if (p.x < 0.0 && p.y > 0.0) {
                ++local_bins[1];               // Quadrant II
            } else if (p.x < 0.0 && p.y < 0.0) {
                ++local_bins[2];               // Quadrant III
            } else if (p.x > 0.0 && p.y < 0.0) {
                ++local_bins[3];               // Quadrant IV
            }
            // Points with x == 0 or y == 0 are ignored.
        }

        // Combine the thread‑local results into the shared bins.
        #pragma omp critical
        {
            for (int q = 0; q < 4; ++q) {
                bins[q] += local_bins[q];
            }
        }
    }
